   flash('success','Product saved successfully.');go('products');
  }
  if($action==='category_save'){require_role(['admin','manager']);$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Category name is required.');$pdo->prepare('INSERT IGNORE INTO categories(name) VALUES(?)')->execute([$name]);flash('success','Category saved.');go('products');}
  if($action==='checkout'){
