   foreach($lines as $line){$p=$line['p'];$qty=$line['qty'];$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,sku,quantity,unit_price,unit_cost,line_total) VALUES(?,?,?,?,?,?,?,?)')->execute([$saleId,$p['id'],$p['name'],$p['sku'],$qty,$p['selling_price'],$p['cost_price'],$line['line']]);$after=(int)$p['quantity']-$qty;$pdo->prepare('UPDATE products SET quantity=? WHERE id=?')->execute([$after,$p['id']]);$pdo->prepare("INSERT INTO stock_movements(product_id,user_id,movement_type,quantity_change,quantity_after,reference) VALUES(?,?,'sale',?,?,?)")->execute([$p['id'],$me['id'],-$qty,$after,$receipt]);}
   audit($pdo,'sale_completed','sale',$saleId,['receipt'=>$receipt,'total'=>$total]);$pdo->commit();$_SESSION['last_receipt']=$saleId;flash('success','Sale completed. Receipt '.$receipt);go('sales');
