   $pdo->beginTransaction();$q=$pdo->prepare("SELECT id,receipt_no,status FROM sales WHERE id=? FOR UPDATE");$q->execute([$saleId]);$sale=$q->fetch();if(!$sale||$sale['status']!=='completed')throw new RuntimeException('Only completed sales can be voided, and each sale can be voided once.');
   $q=$pdo->prepare('SELECT product_id,quantity FROM sale_items WHERE sale_id=?');$q->execute([$saleId]);$items=$q->fetchAll();
