   $pdo->prepare("UPDATE sales SET status='voided' WHERE id=?")->execute([$saleId]);audit($pdo,'sale_voided','sale',$saleId,['receipt'=>$sale['receipt_no'],'reason'=>$reason]);$pdo->commit();flash('success','Sale voided and sold quantities returned to inventory.');go('sales');
