  if($action==='purchase_receive'){
   require_role(['admin','manager']);$supplier=(int)($_POST['supplier_id']??0);$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$cost=(float)($_POST['unit_cost']??0);$ref=trim($_POST['reference_no']??'');$notes=trim($_POST['notes']??'');
   if($pid<1||$qty<1||$cost<0)throw new RuntimeException('Choose a product and enter a positive quantity and valid cost.');
   if($ref==='')$ref='PO-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
