   $subtotal=round($qty*$cost,2);$pdo->prepare("INSERT INTO purchases(supplier_id,reference_no,status,subtotal,notes,created_by) VALUES(?,?,'received',?,?,?)")->execute([$supplier?:null,$ref,$subtotal,$notes,$me['id']]);$purchaseId=(int)$pdo->lastInsertId();
   $pdo->prepare('INSERT INTO purchase_items(purchase_id,product_id,quantity,unit_cost,line_total) VALUES(?,?,?,?,?)')->execute([$purchaseId,$pid,$qty,$cost,$subtotal]);
