<div class="page-title"><div><p class="eyebrow">CHECKOUT COUNTER</p><h1>Point of Sale</h1><div class="muted">Build a cart, take payment and issue a receipt.</div></div></div>
<div class="pos-layout"><section class="card"><input id="search" placeholder="Search products by name or SKU…" ><div class="product-grid" id="productGrid" style="margin-top:14px"><?php foreach($products as $p):?><button type="button" class="product-tile" data-id="<?=$p['id']?>" data-name="<?=h($p['name'])?>" data-price="<?=h((string)$p['selling_price'])?>" data-stock="<?=$p['quantity']?>" data-search="<?=h(strtolower($p['name'].' '.$p['sku']))?>" <?=$p['quantity']<1?'disabled':''?>><small><?=h($p['sku'])?></small><strong><?=h($p['name'])?></strong><span><?=money($p['selling_price'])?></span><small><?=$p['quantity']?> available</small></button><?php endforeach?></div></section><aside class="card"><div class="card-head"><h2>Current sale</h2><button type="button" class="btn secondary" id="clearCart">Clear</button></div><div id="cart"><div class="empty">Select products to begin.</div></div><label>Discount (KES)<input id="discount" type="number" min="0" step=".01" value="0" ></label><label>Payment method<select id="method"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option><option value="card">Card</option><option value="other">Other</option></select></label><label>Amount received (KES)<input id="paid" type="number" min="0" step=".01" value="0"></label><div class="totals" id="totals"></div><div id="changePreview" class="muted" aria-live="polite"></div><button type="button" class="btn primary full" id="completeSale" style="margin-top:15px">Complete sale</button><form id="checkoutForm" method="post" hidden><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input name="action" value="checkout"><input name="cart" id="cartData"><input name="discount" id="discountData"><input name="amount_paid" id="paidData"><input name="payment_method" id="methodData"></form></aside></div>
<script>
(function(){'use strict';
const cart=new Map(),byId=id=>document.getElementById(id);
const fmt=n=>'KSh '+Number(n).toFixed(2);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderCart(){let subtotal=0;const el=byId('cart');if(!cart.size)el.innerHTML='<div class="empty">Select products to begin.</div>';else el.innerHTML=[...cart.values()].map(x=>{const line=x.price*x.qty;subtotal+=line;return '<div class="cart-line"><div><strong>'+esc(x.name)+'</strong><div class="muted">'+x.qty+' × '+fmt(x.price)+'</div><button type="button" class="btn secondary" data-id="'+x.id+'" data-delta="-1">−</button> <button type="button" class="btn secondary" data-id="'+x.id+'" data-delta="1">＋</button></div><strong>'+fmt(line)+'</strong></div>';}).join('');const d=Math.min(subtotal,Math.max(0,Number(byId('discount').value)||0));byId('totals').innerHTML='<div class="total-row"><span>Subtotal</span><strong>'+fmt(subtotal)+'</strong></div><div class="total-row"><span>Discount</span><strong>− '+fmt(d)+'</strong></div><div class="total-row grand"><span>Total</span><span>'+fmt(subtotal-d)+'</span></div>';previewChange();}
function previewChange(){const sub=[...cart.values()].reduce((a,x)=>a+x.price*x.qty,0),d=Math.min(sub,Math.max(0,Number(byId('discount').value)||0)),paid=Math.max(0,Number(byId('paid').value)||0),due=sub-d;byId('changePreview').textContent=paid>=due?'Change due: '+fmt(paid-due):'Still due: '+fmt(due-paid);}
function addItem(tile){const id=Number(tile.dataset.id),stock=Number(tile.dataset.stock),price=Number(tile.dataset.price);if(stock<1)return;const x=cart.get(id)||{id,name:tile.dataset.name,price,qty:0,stock};if(x.qty>=stock){alert('No more stock available.');return;}x.qty++;cart.set(id,x);renderCart();}
byId('productGrid').addEventListener('click',e=>{const tile=e.target.closest('.product-tile');if(tile&&!tile.disabled)addItem(tile);});
byId('cart').addEventListener('click',e=>{const b=e.target.closest('[data-id][data-delta]');if(!b)return;const x=cart.get(Number(b.dataset.id));if(!x)return;x.qty+=Number(b.dataset.delta);if(x.qty<1)cart.delete(x.id);else if(x.qty>x.stock)x.qty=x.stock;renderCart();});
byId('discount').addEventListener('input',renderCart);byId('paid').addEventListener('input',previewChange);
byId('search').addEventListener('input',()=>{const q=byId('search').value.trim().toLowerCase();document.querySelectorAll('.product-tile').forEach(t=>t.hidden=!t.dataset.search.includes(q));});
byId('clearCart').addEventListener('click',()=>{cart.clear();renderCart();});
byId('completeSale').addEventListener('click',()=>{if(!cart.size){alert('Add at least one product.');return;}const sub=[...cart.values()].reduce((a,x)=>a+x.price*x.qty,0),d=Math.max(0,Number(byId('discount').value)||0),paid=Math.max(0,Number(byId('paid').value)||0);if(d>sub){alert('Discount cannot exceed subtotal.');return;}if(paid+0.0001<sub-d){alert('Amount received is less than the total due.');return;}byId('cartData').value=JSON.stringify([...cart.values()].map(x=>({id:x.id,qty:x.qty})));byId('discountData').value=String(d);byId('paidData').value=String(paid);byId('methodData').value=byId('method').value;byId('checkoutForm').requestSubmit();});
renderCart();})();
</script>
